package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.jsoup.nodes.Element.prepend;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

@RunWith(JUnit4.class)
public class Element_prepend_TriageGen2Test {

    @Test
    public void testPrepend_NilHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend(null);
        assertEquals(0, element.children().size());
    }

    @Test
    public void testPrepend_EmptyHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend("");
        assertEquals(0, element.children().size());
    }

    @Test
    public void testPrepend_SimpleHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend("<p>hello</p>");
        assertEquals(1, element.children().size());
        assertEquals("hello", element.children().get(0).text());
    }

    @Test
    public void testPrepend_MultipleHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend("<p>hello</p><p>world</p>");
        assertEquals(2, element.children().size());
        assertEquals("hello", element.children().get(0).text());
        assertEquals("world", element.children().get(1).text());
    }

    @Test
    public void testPrepend_ValidHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend("<p>hello</p><div>world</div>");
        assertEquals(2, element.children().size());
        assertEquals("hello", element.children().get(0).text());
        assertEquals("world", element.children().get(1).text());
    }

    @Test
    public void testPrepend_InvalidHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend("<p>hello</p><div>world</div><script>alert('xss')</script>");
        assertEquals(2, element.children().size());
        assertEquals("hello", element.children().get(0).text());
        assertEquals("world", element.children().get(1).text());
    }

    @Test
    public void testPrepend_NullHtml() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend(null);
        assertEquals(0, element.children().size());
    }

    @Test
    public void testPrepend_NullElement() {
        Element element = null;
        try {
            element.prepend("<p>hello</p>");
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // expected
        }
    }

    @Test
    public void testPrepend_NullParser() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        ParseError error = new ParseError();
        Parser parser = new Parser() {
            @Override
            public void error(Error error) {
                throw new ParseError();
            }
        };
        try {
            element.prepend(parser.parseBodyFragment("<p>hello</p>", "https://example.com").body());
            fail("Expected ParseError");
        } catch (ParseError e) {
            // expected
        }
    }

    @Test
    public void testPrepend_InvalidHtml_Element() {
        Element element = new Element(Tag.valueOf("p"), "https://example.com");
        element.prepend("<p>hello</p><div>world</div><script>alert('xss')</script>");
        assertEquals(2, element.children().size());
        assertEquals("hello", element.children().get(0).text());
        assertEquals("world", element.children().get(1).text());
    }
}
